#include <stack>
#include <deque>
#include <vector>
#include <list>

int main() {
    // 1. Default (uses std::deque)
    std::stack<int> s_default;

    // 2. Using std::vector as underlying container
    std::stack<int, std::vector<int>> s_vec;

    // 3. Using std::list as underlying container
    std::stack<int, std::list<int>> s_list;

    s_vec.push(10);
    // s_vec.top() internally calls vector::back()
}
